const nowUtc = typeof DateTime !== 'undefined' ? DateTime.utc() : null;
const now = new Date();

return $input.all().filter(item => {
  const row = item.json;
  try {
    if (row.scheduled_utc) {
      return new Date(row.scheduled_utc) <= now;
    }
    if (row["Scheduled Date"] && row["Scheduled Time"]) {
      const dateStr = String(row["Scheduled Date"]).trim();
      let timeStr = String(row["Scheduled Time"]).trim();
      const zone = row["Time Zone"] ? String(row["Time Zone"]).trim() : 'UTC';

      if (typeof DateTime !== 'undefined') {
        let dt = null;
        // 1. Try 12-hour format with AM/PM (e.g. 12:15:00 AM or 12:15 AM)
        if (/[ap]m/i.test(timeStr)) {
          dt = DateTime.fromFormat(dateStr + " " + timeStr, 'yyyy-MM-dd h:mm:ss a', { zone });
          if (!dt.isValid) {
            dt = DateTime.fromFormat(dateStr + " " + timeStr, 'yyyy-MM-dd h:mm a', { zone });
          }
        } else {
          // 2. Try 24-hour format (e.g. 00:15 or 00:15:00)
          const isoTime = timeStr.length === 5 ? timeStr + ":00" : timeStr;
          dt = DateTime.fromISO(dateStr + "T" + isoTime, { zone });
        }

        if (dt && dt.isValid) {
          return dt.toUTC() <= nowUtc;
        }
      }

      // Fallback
      const postDate = new Date(dateStr + " " + timeStr);
      return !isNaN(postDate.getTime()) && postDate <= now;
    }
    return false;
  } catch (e) {
    return false;
  }
});

const post = $('Is Status Still Publishing?').first().json;
const client = $('Get Client Account IDs (Tab B)').first()?.json || {};
const prep = $('Prepare Direct Media URL').first().json;

// Default account IDs if client is not in Tab B
const igId = client["Instagram Account ID"] || "17841439037630316";
const fbId = client["Facebook Page ID"] || "1454740611044963";
const liId = client["LinkedIn Organization ID"] || "144029551";

let mediaUrl = prep.directUrl;

// 1. Detect Media Type (Video vs Image)
let isVideo = /\.(mp4|mov|avi|m4v)(\?.*)?$/i.test(mediaUrl) || mediaUrl.includes('/video/') || mediaUrl.includes('download/video');
let isImage = !isVideo;

// 1a. Check explicit column if specified in Google Sheet
const explicitType = (post["Media Type"] || post["Post Type"] || post["Type"] || post["Media Format"] || "").toString().trim().toLowerCase();
if (explicitType === "video" || explicitType === "reel" || explicitType === "reels") {
  isVideo = true;
  isImage = false;
} else if (explicitType === "image" || explicitType === "photo" || explicitType === "post") {
  isImage = true;
  isVideo = false;
}

// 1b. Check inspected HTTP HEAD headers
if (!isVideo && !isImage) {
  try {
    const headNode = $('Inspect Media URL (HEAD)').first();
    if (headNode && headNode.json && headNode.json.headers) {
      const cType = (headNode.json.headers['content-type'] || '').toLowerCase();
      const cDisp = (headNode.json.headers['content-disposition'] || '').toLowerCase();
      if (cType.startsWith('video/') || /\.(mp4|mov|avi|m4v)/i.test(cDisp)) {
        isVideo = true;
        isImage = false;
      } else if (cType.startsWith('image/') || /\.(jpeg|jpg|png|webp|gif)/i.test(cDisp)) {
        isImage = true;
        isVideo = false;
      }
    }
  } catch (e) {}
}

// Universal Instagram Image Optimizer:
// Converts WebP, AVIF, PNG, odd aspect ratios, or non-standard image URLs into a guaranteed 100% compliant JPEG
let optimizedIgImageUrl = mediaUrl;
if (!isVideo && mediaUrl) {
  if (!mediaUrl.includes('drive.usercontent.google.com') && !mediaUrl.includes('wsrv.nl')) {
    optimizedIgImageUrl = 'https://wsrv.nl/?url=' + encodeURIComponent(mediaUrl) + '&output=jpg&q=85';
  }
}

// 2. Prepare Facebook Payload
let fbEndpoint = 'feed';
let fbBody = {
  message: post["Facebook Caption"] || ""
};

if (mediaUrl) {
  if (isVideo) {
    fbEndpoint = 'videos';
    fbBody = {
      description: post["Facebook Caption"] || "",
      file_url: mediaUrl
    };
  } else {
    fbEndpoint = 'photos';
    fbBody = {
      caption: post["Facebook Caption"] || "",
      url: optimizedIgImageUrl
    };
  }
}

// 3. Prepare Instagram Feed / Reel Payload
let igBody = {};
if (isVideo) {
  igBody = {
    media_type: "REELS",
    video_url: mediaUrl,
    caption: post["Instagram Caption"] || ""
  };
} else {
  igBody = {
    image_url: optimizedIgImageUrl,
    caption: post["Instagram Caption"] || ""
  };
}

// 4. Process Photo & Video Tags (Produces the native tag icon on Instagram)
const rawTags = (post["Photo Tags"] || post["Instagram User Tags"] || post["User Tags"] || post["IG Tags"] || post["Tags"] || "").toString().trim();
let tagList = [];
if (rawTags) {
  tagList = rawTags
    .split(/[\s,]+/)
    .map(t => t.trim().replace(/^@/, ''))
    .filter(Boolean)
    .slice(0, 20);

  if (tagList.length > 0) {
    if (isVideo) {
      igBody.user_tags = tagList.map(username => ({ username }));
    } else {
      if (tagList.length === 1) {
        igBody.user_tags = [{ username: tagList[0], x: 0.5, y: 0.5 }];
      } else {
        igBody.user_tags = tagList.map((username, index) => ({
          username: username,
          x: Number((0.25 + (index % 3) * 0.25).toFixed(2)),
          y: Number((0.35 + Math.floor(index / 3) * 0.2).toFixed(2))
        }));
      }
    }
  }
}

// 5. Prepare Instagram Story Payload
let igStoryBody = null;
const allowStory = (post["Story"] || post["Instagram Story"] || "Yes").toString().trim().toLowerCase() !== "no";
if (mediaUrl && allowStory && (post.Instagram === "Yes" || post.Instagram === true)) {
  if (isVideo) {
    igStoryBody = {
      media_type: "STORIES",
      video_url: mediaUrl
    };
  } else {
    igStoryBody = {
      media_type: "STORIES",
      image_url: optimizedIgImageUrl
    };
  }
  if (tagList.length > 0) {
    igStoryBody.user_tags = tagList.map(username => ({
      username: username,
      x: 0.5,
      y: 0.5
    }));
  }
}

// 6. Prepare LinkedIn Payload
const rawLiId = (liId || "7jngID0YwF").trim();
let authorUrn = rawLiId;
if (!authorUrn.startsWith('urn:li:')) {
  if (/^\d+$/.test(authorUrn)) {
    authorUrn = 'urn:li:organization:' + authorUrn;
  } else {
    authorUrn = 'urn:li:person:' + authorUrn;
  }
}

let liShareContent = {
  shareCommentary: {
    text: post["LinkedIn Caption"] || ""
  },
  shareMediaCategory: mediaUrl ? "ARTICLE" : "NONE"
};

if (mediaUrl) {
  liShareContent.media = [
    {
      status: "READY",
      originalUrl: mediaUrl,
      title: {
        text: post["Content Name"] || "Post"
      }
    }
  ];
}

const liBody = {
  author: authorUrn,
  lifecycleState: "PUBLISHED",
  specificContent: {
    "com.linkedin.ugc.ShareContent": liShareContent
  },
  visibility: {
    "com.linkedin.ugc.MemberNetworkVisibility": "PUBLIC"
  }
};

return [{
  json: {
    ...post,
    client: client,
    instagram_id: igId,
    facebook_id: fbId,
    linkedin_id: liId,
    is_video: isVideo,
    fb_endpoint: fbEndpoint,
    fb_body: fbBody,
    ig_body: igBody,
    ig_story_body: igStoryBody,
    post_story: !!igStoryBody,
    li_body: liBody
  }
}];

function extractErrorMsg(errObj) {
  if (!errObj) return 'Unknown error';
  if (typeof errObj === 'string') {
    const jsonMatch = errObj.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      try {
        const unescaped = jsonMatch[0].replace(/\\"/g, '"');
        const parsed = JSON.parse(unescaped);
        return extractErrorMsg(parsed);
      } catch (e) {
        try {
          const parsed = JSON.parse(jsonMatch[0]);
          return extractErrorMsg(parsed);
        } catch (e2) {}
      }
    }
    return errObj;
  }
  if (errObj.error_user_msg) return errObj.error_user_msg;
  if (errObj.error && errObj.error.error_user_msg) return errObj.error.error_user_msg;
  if (errObj.error && errObj.error.message) return errObj.error.message;
  if (errObj.message) return extractErrorMsg(errObj.message);
  return JSON.stringify(errObj);
}

const post = $('Merge Client IDs & Prepare Payloads').first().json;
const publishedUrls = [];
const errors = [];
let igUrl = "";
let fbUrl = "";
let liUrl = "";

// 1. Instagram
if (post.Instagram === "Yes" || post.Instagram === true) {
  try {
    let igCreate = null;
    try {
      igCreate = $('Instagram: Create Media Container').first();
    } catch (e) {}

    let igStatusNode = null;
    try {
      igStatusNode = $('Instagram: Check Container Status').first();
    } catch (e) {}

    let igPub = null;
    try {
      igPub = $('Instagram: Publish Container').first();
    } catch (e) {}

    // Check if permalink was retrieved (either direct or fallback query)
    try {
      const igPerm = $('Instagram: Get Published Permalink').first();
      if (igPerm && igPerm.json) {
        if (igPerm.json.permalink) {
          igUrl = igPerm.json.permalink;
        } else if (igPerm.json.data && igPerm.json.data[0] && igPerm.json.data[0].permalink) {
          igUrl = igPerm.json.data[0].permalink;
        }
      }
    } catch (e) {}

    if (igUrl) {
      publishedUrls.push(igUrl);
    } else if (igCreate && igCreate.json && igCreate.json.error) {
      errors.push("Instagram container creation error: " + extractErrorMsg(igCreate.json.error));
    } else if (!igCreate || !igCreate.json || !igCreate.json.id) {
      errors.push("Instagram container creation failed (no ID returned)");
    } else if (igStatusNode && igStatusNode.json && igStatusNode.json.status_code === 'ERROR') {
      let detail = igStatusNode.json.status || "Media upload failed on Instagram";
      errors.push("Instagram media error: " + detail + " (Aspect ratio must be between 4:5 and 1.91:1, and min 320x320px)");
    } else if (igPub && igPub.json && igPub.json.error) {
      errors.push("Instagram publish error: " + extractErrorMsg(igPub.json.error));
    } else if (igPub && igPub.json && igPub.json.id) {
      igUrl = "https://www.instagram.com/p/" + igPub.json.id + "/";
      publishedUrls.push(igUrl);
    } else {
      errors.push("Instagram publish failed (no post ID or permalink returned)");
    }
  } catch (e) {
    errors.push("Instagram error: " + e.message);
  }
}

// 2. Facebook
if (post.Facebook === "Yes" || post.Facebook === true) {
  try {
    let fbPub = null;
    try {
      fbPub = $('Facebook: Publish Photo/Post').first();
    } catch (e) {
      errors.push("Facebook error: " + e.message);
    }
    if (fbPub && fbPub.json) {
      if (fbPub.json.error) {
        errors.push("Facebook error: " + extractErrorMsg(fbPub.json.error));
      } else {
        const photoId = fbPub.json.id;
        const postId = fbPub.json.post_id;
        if (photoId) {
          fbUrl = "https://www.facebook.com/photo.php?fbid=" + photoId;
        } else if (postId) {
          const storyId = postId.includes('_') ? postId.split('_')[1] : postId;
          fbUrl = "https://www.facebook.com/permalink.php?story_fbid=" + storyId + "&id=" + post.facebook_id;
        }
      }
    }

    if (fbUrl) {
      publishedUrls.push(fbUrl);
    } else if (fbPub && (!fbPub.json || !fbPub.json.error)) {
      errors.push("Facebook failed to return post ID");
    }
  } catch (e) {
    errors.push("Facebook error: " + e.message);
  }
}

// 3. LinkedIn
if (post.LinkedIn === "Yes" || post.LinkedIn === true) {
  try {
    let liPub = null;
    try {
      liPub = $('LinkedIn: Publish Post').first();
    } catch (e) {
      errors.push("LinkedIn error: " + e.message);
    }
    if (liPub && liPub.json && liPub.json.id) {
      liUrl = "https://www.linkedin.com/feed/update/" + liPub.json.id;
      publishedUrls.push(liUrl);
    } else if (liPub && liPub.json && (liPub.json.message || liPub.json.error)) {
      errors.push("LinkedIn error: " + extractErrorMsg(liPub.json.error || liPub.json.message));
    } else if (liPub) {
      errors.push("LinkedIn failed to return share ID");
    }
  } catch (e) {
    errors.push("LinkedIn error: " + e.message);
  }
}

const allSuccessful = errors.length === 0;

let finalPublishedUrl = "";
if (publishedUrls.length === 1) {
  finalPublishedUrl = '=HYPERLINK("' + publishedUrls[0] + '", "' + publishedUrls[0] + '")';
} else if (publishedUrls.length > 1) {
  finalPublishedUrl = publishedUrls.join("\n");
}

return [{
  json: {
    "Post ID": post["Post ID"],
    "Status": allSuccessful ? "Posted" : "Failed",
    "Published URL": finalPublishedUrl,
    "Error Message": errors.join("; "),
    "instagram_url": igUrl || "None",
    "facebook_url": fbUrl || "None",
    "linkedin_url": liUrl || "None"
  }
}];

const post = $('Is Status Still Publishing?').first().json;
const client = $input.first().json;

let rawUrl = (post["Media URL"] || "").trim();
let directUrl = rawUrl;

// 1. Google Images Search Result (copied from Google Images)
if (directUrl.includes('google.com/imgres') || directUrl.includes('/imgres?')) {
  const m = directUrl.match(/[?&]imgurl=([^&]+)/i);
  if (m) {
    try {
      directUrl = decodeURIComponent(m[1]);
    } catch (e) {}
  }
}

// 2. Google Drive Links
if (directUrl.includes('drive.google.com') || directUrl.includes('docs.google.com')) {
  const m = directUrl.match(/\/d\/([a-zA-Z0-9_-]+)/) || directUrl.match(/[?&]id=([a-zA-Z0-9_-]+)/);
  if (m) {
    directUrl = "https://drive.usercontent.google.com/download?id=" + m[1] + "&export=download&authuser=0";
  }
}

// 3. Pexels Photo Page Links -> Direct High-Res JPEG
if (directUrl.includes('pexels.com') && !directUrl.includes('images.pexels.com')) {
  const m = directUrl.match(/\/photo\/(?:[^\/]*?-)?(\d+)(?:\/|\?|#|$)/i) || directUrl.match(/pexels\.com\/.*?(\d{5,})/i);
  if (m) {
    directUrl = "https://images.pexels.com/photos/" + m[1] + "/pexels-photo-" + m[1] + ".jpeg?auto=compress&cs=tinysrgb&fit=crop&h=1200&w=1200";
  }
}

// 4. Dropbox Links -> Direct Raw Media
if (directUrl.includes('dropbox.com')) {
  if (directUrl.includes('dl=0')) {
    directUrl = directUrl.replace('dl=0', 'raw=1');
  } else if (!directUrl.includes('raw=1')) {
    directUrl = directUrl + (directUrl.includes('?') ? '&raw=1' : '?raw=1');
  }
}

// 5. Imgur Page Links -> Direct Image
if (directUrl.includes('imgur.com') && !directUrl.includes('i.imgur.com')) {
  const m = directUrl.match(/imgur\.com\/(?:gallery\/|a\/)?([a-zA-Z0-9]+)(?:[?#].*)?$/i);
  if (m && !['a', 'gallery', 'upload'].includes(m[1])) {
    directUrl = "https://i.imgur.com/" + m[1] + ".jpg";
  }
}

// 6. Unsplash Image Links (ensure safe square crop & resolution)
if (directUrl.includes('images.unsplash.com')) {
  if (!directUrl.includes('w=') && !directUrl.includes('h=')) {
    directUrl = directUrl + (directUrl.includes('?') ? '&w=1200&auto=format&fit=crop&q=80' : '?w=1200&auto=format&fit=crop&q=80');
  }
}

// 7. Strip tracking fragments
directUrl = directUrl.split('#')[0];

return [{
  json: {
    directUrl: directUrl || "https://httpbin.org/status/200",
    client: client
  }
}];

