={{ (() => {
  const post = $('Is Status Still Publishing?').first().json;
  const urls = ($json["Published URL"] || "").split("\n").filter(Boolean);

  let linkButtons = "";
  if (urls.length === 0) {
    linkButtons = "<p style='color: #888; font-style: italic;'>No published URLs available.</p>";
  } else {
    linkButtons = urls.map(u => {
      let label = "View Post";
      let btnColor = "#1877f2";
