        label = u.includes("/reel/") ? "📸 View on Instagram Reel" : "📸 View on Instagram Post";
        btnColor = "#E1306C";
      } else if (u.includes("facebook.com")) {
        label = "📘 View on Facebook";
        btnColor = "#1877f2";
      } else if (u.includes("linkedin.com")) {
        label = "💼 View on LinkedIn";
        btnColor = "#0A66C2";
