      '</div>';
    }).join("");
  }

  const errorBlock = $json["Error Message"] ? '<div style="background-color: #ffebee; border-left: 4px solid #f44336; padding: 12px; margin: 15px 0; border-radius: 4px; color: #c62828;"><strong>Error Details:</strong><br>' + $json["Error Message"] + '</div>' : '';

  return '<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 25px; border: 1px solid #e0e0e0; border-radius: 8px; background-color: #ffffff;">' +
    '<h2 style="color: ' + ($json.Status === 'Posted' ? '#2e7d32' : '#d32f2f') + '; margin-top: 0;">' + ($json.Status === 'Posted' ? '🎉 Post Published Successfully!' : '⚠️ Post Publishing Alert') + '</h2>' +
    '<p style="color: #555; font-size: 14px; margin-bottom: 20px;">Here is the summary of your scheduled post from your Content Calendar:</p>' +
    '<table style="width: 100%; border-collapse: collapse; margin-bottom: 20px; font-size: 14px;">' +
      '<tr style="border-bottom: 1px solid #eee;"><td style="padding: 8px 0; font-weight: bold; color: #333; width: 140px;">Content Name:</td><td style="padding: 8px 0; color: #555;">' + (post["Content Name"] || "N/A") + '</td></tr>' +
      '<tr style="border-bottom: 1px solid #eee;"><td style="padding: 8px 0; font-weight: bold; color: #333;">Client:</td><td style="padding: 8px 0; color: #555;">' + (post["Client Name"] || "N/A") + '</td></tr>' +
      '<tr style="border-bottom: 1px solid #eee;"><td style="padding: 8px 0; font-weight: bold; color: #333;">Status:</td><td style="padding: 8px 0; font-weight: bold; color: ' + ($json.Status === 'Posted' ? '#2e7d32' : '#d32f2f') + ';">' + $json.Status + '</td></tr>' +
    '</table>' +
    '<h3 style="color: #333; margin-bottom: 12px;">Live Published Links:</h3>' +
    '<div style="background-color: #f8f9fa; padding: 15px; border-radius: 6px; border: 1px solid #e9ecef;">' + linkButtons + '</div>' +
    errorBlock +
    '<p style="font-size: 11px; color: #888; margin-top: 25px; border-top: 1px solid #eee; padding-top: 10px; text-align: center;">Automated notification sent from n8n Social Media Automation</p>' +
  '</div>';
})() }}

