  messaging_product: 'whatsapp',
  recipient_type: 'individual',
  to: (String($('Get Client Account IDs (Tab B)').first()?.json?.['Phone'] || $('Get Client Account IDs (Tab B)').first()?.json?.['WhatsApp'] || $('Is Status Still Publishing?').first()?.json?.['Phone'] || '918734037481')).replace(/[^0-9]/g, ''),
